\subsection{Problem Setup}
\label{sec:setup}

Let $\mathcal{D} = \mathcal{D}_{\mathrm{real}} \cup \mathcal{D}_{\mathrm{synth}}$ denote a pretraining corpus with contamination ratio $\rho = |\mathcal{D}_{\mathrm{synth}}| / |\mathcal{D}|$, assumed unknown~\citep{cheng2025contamination}.
A detector assigns each sample $x$ a synthetic probability $q(x) \in [0,1]$; following \citet{drayson2025detection}, we weight each sample as
\begin{equation}
  w(x) = (1 - q(x))^{b},
  \label{eq:weight}
\end{equation}
where $b \geq 0$ is a sharpening exponent: $b = 0$ recovers uniform training, while larger $b$ suppresses high-$q$ samples.
\citet{drayson2025detection} select $b$ via validation-set grid search ($b{=}10$ for ${\leq}360$M, $b{=}1$ for 1.7B); we instead derive $b$ per-batch from the batch's $q$-score distribution.

\subsection{Dual-Constraint Framework}
\label{sec:dual}

Given a batch $\mathcal{B} = \{x_1, \ldots, x_B\}$ with scores $q_i = q(x_i)$ and weights $w_i(b) = (1 - q_i)^{b}$, we define two diagnostics.

\paragraph{Effective real proportion.}
Let $r_i = \mathbf{1}[q_i \leq 0.5]$ estimate whether $x_i$ is human-authored.
The \emph{effective real proportion}
\begin{equation}
  \alpha_{\mathrm{eff}}(b) = \frac{\sum_{i=1}^{B} w_i(b) \cdot r_i}{\sum_{i=1}^{B} w_i(b)}
  \label{eq:alpha}
\end{equation}
measures the share of weight allocated to likely-real samples.
Since $r_i$ is binary, $\aeff(0)$ takes only $B{+}1$ discrete values; however, for $b > 0$ the weights $w_i(b)$ vary continuously in $b$, making $\aeff(b)$ a continuous function amenable to bisection.
$\aeff$ is a proxy for the true real fraction (Pearson $r \approx 0.70$; Appendix~\ref{app:alpha_validation}); post-hoc calibration~\citep{guo2017calibration} yields ECE\,=\,0.05.

\paragraph{Effective sample size.}
Kish's effective sample size~\citep{kish1965survey}
\begin{equation}
  \mathrm{ESS}(b) = \frac{\bigl(\sum_{i=1}^{B} w_i(b)\bigr)^{2}}{\sum_{i=1}^{B} w_i(b)^{2}}
  \label{eq:ess}
\end{equation}
quantifies how many equally-weighted samples the weighted batch is equivalent to; $\mathrm{ESS}(0) = B$ and $\mathrm{ESS}$ decreases monotonically in $b$ (Proposition~\ref{prop:ess_mono}, Appendix~\ref{app:proofs}).

\paragraph{Dual constraints.}
$\alpha_{\mathrm{eff}}(b)$ is non-decreasing (Proposition~\ref{prop:monotone}) and $\mathrm{ESS}(b)$ is decreasing, yielding opposing bounds on $b$:
\begin{enumerate}[nosep,leftmargin=*]
  \item \textbf{Quality floor}: $\alpha_{\mathrm{eff}}(b) \geq \tau$ defines a lower bound $b_\tau$, motivated by convergence theory under contamination~\citep{wang2026survive}.
  Note: \citet{wang2026survive} assume known $\alpha$; we replace it with estimated $\aeff(b)$, so the guarantee holds modulo detector calibration.
  \item \textbf{Stability ceiling}: $\mathrm{ESS}(b) \geq n_{\min}$ defines an upper bound $b_{\mathrm{ESS}}$, preventing gradient degeneration from weight concentration.
\end{enumerate}
The optimal sharpening exponent is
\begin{equation}
  b^{*} = \begin{cases}
    0        & \text{if } \alpha_{\mathrm{eff}}(0) \geq \tau, \\
    b_\tau   & \text{if } b_\tau \leq b_{\mathrm{ESS}}, \\
    b_{\mathrm{ESS}} & \text{otherwise},
  \end{cases}
  \label{eq:bstar}
\end{equation}
implementing \emph{minimum intervention}: apply the smallest $b$ that achieves the quality floor.
When constraints conflict ($b_\tau > b_{\mathrm{ESS}}$), stability takes precedence.
Each batch falls into one of three regimes---clean ($\aeff(0) \geq \tau$), $\aeff$-binding ($b^{*} = b_\tau$), or ESS-binding ($b^{*} = b_{\mathrm{ESS}}$)---whose relative frequencies we report in \S\ref{sec:regime}.

\paragraph{Implementation.}
$b^{*}$ is found via bisection on $\aeff(\cdot)$ and $\mathrm{ESS}(\cdot)$; given $b^{*}$, normalized weights $\pi_i = w_i(b^{*}) / \sum_j w_j(b^{*})$ define the weighted loss $\mathcal{L} = \sum_i \pi_i \ell_i$ (Algorithm~\ref{alg:bstar}, Appendix~\ref{app:algorithm}).
This \emph{loss reweighting} maintains continuous gradients, unlike the SIR resampling of \citet{drayson2025detection}.
Default hyperparameters are $\tau{=}0.7$ and $\nmin{=}\lfloor B/2 \rfloor$; sensitivity analysis in \S\ref{sec:sensitivity}.

\section{Proofs}
\label{app:proofs}

\begin{proposition}[$\alpha_{\mathrm{eff}}$ monotonicity]
\label{prop:monotone}
$\alpha_{\mathrm{eff}}(b)$ is non-decreasing in $b$, and strictly increasing whenever the batch contains at least one sample with $q_i \in (0,1)$ and $r_i$ is not constant.
\end{proposition}

\begin{proof}[Proof of Proposition~\ref{prop:monotone}]
Let $w_i(b) = (1 - q_i)^b$, $W(b) = \sum_{j=1}^B w_j(b)$, and $\pi_i(b) = w_i(b) / W(b)$.
Then
\begin{equation*}
  \alpha_{\mathrm{eff}}(b) = \sum_{i=1}^{B} \pi_i(b)\, r_i,
\end{equation*}
where $r_i \in \{0, 1\}$ indicates whether sample $i$ is real.
Taking the derivative with respect to $b$:
\begin{align*}
  \frac{d\pi_i}{db}
  &= \pi_i \!\left(\frac{d \ln w_i}{db} - \frac{d \ln W}{db}\right) \\
  &= \pi_i \!\left(\ln(1{-}q_i) - \textstyle\sum_j \pi_j \ln(1{-}q_j)\right).
\end{align*}
Substituting,
\begin{align*}
  \frac{d\alpha_{\mathrm{eff}}}{db}
  &= \sum_i r_i\, \pi_i \!\left(\ln(1{-}q_i) - \mathbb{E}_{\pi}[\ln(1{-}q)]\right) \\
  &= \mathrm{Cov}_{\pi}\!\bigl(r_i,\, \ln(1{-}q_i)\bigr).
\end{align*}
Since $r_i = \mathbf{1}[q_i \leq 0.5]$, the indicator $r_i$ and $\ln(1{-}q_i)$ are positively associated by construction, so the covariance is non-negative.
\end{proof}

\begin{proposition}[ESS monotonicity]
\label{prop:ess_mono}
$\mathrm{ESS}(b)$ is non-increasing in $b$, and strictly decreasing whenever the batch contains at least two samples with distinct $q$-values.
\end{proposition}

\begin{proof}
Write $\mathrm{ESS}(b) = 1 / \sum_i \pi_i(b)^2$, where $\pi_i(b) = w_i(b) / W(b)$.
The denominator $\sum_i \pi_i^2$ is the Herfindahl index $H$.
Differentiating $H$ with respect to $b$:
\begin{equation*}
  \frac{dH}{db} = 2 \sum_i \pi_i^2 \bigl(\ln(1{-}q_i) - \mathbb{E}_{\pi}[\ln(1{-}q)]\bigr).
\end{equation*}
Since $\pi_i \propto (1{-}q_i)^b$, larger $\pi_i$ implies larger $\ln(1{-}q_i)$; the $\pi^2$-weighted sum assigns greater mass to terms where $\ln(1{-}q_i) > \mathbb{E}_\pi[\ln(1{-}q)]$, so $dH/db \geq 0$, with strict inequality when at least two $q$-values differ.
Thus $H$ is non-decreasing and $\mathrm{ESS} = 1/H$ is non-increasing.
This is a standard property of exponential tilting~\citep{kish1965survey,owen2013mc}.
\end{proof}

\section{Algorithm Pseudocode}
\label{app:algorithm}

\begin{algorithm}[h]
\caption{Per-batch adaptive $b^{*}$ selection}
\label{alg:bstar}
\begin{algorithmic}[1]
\REQUIRE Batch scores $\{q_i\}_{i=1}^{B}$, indicators $\{r_i\}$, quality threshold~$\tau$, ESS floor~$n_{\min}$, search bound~$b_{\max}$, tolerance~$\varepsilon$
\ENSURE Optimal sharpening exponent $b^{*}$
\IF{$\alpha_{\mathrm{eff}}(0) \geq \tau$}
  \STATE \textbf{return} $0$ \COMMENT{clean batch}
\ENDIF
\STATE $b_\tau \gets \textsc{Bisect}(\alpha_{\mathrm{eff}}(\cdot){=}\tau,\; [0, b_{\max}],\; \varepsilon)$
\IF{$\mathrm{ESS}(b_\tau) \geq n_{\min}$}
  \STATE \textbf{return} $b_\tau$ \COMMENT{$\alpha_{\mathrm{eff}}$-binding}
\ELSE
  \STATE $b_{\mathrm{ESS}} \gets \textsc{Bisect}(\mathrm{ESS}(\cdot){=}n_{\min},\; [0, b_{\max}],\; \varepsilon)$
  \STATE \textbf{return} $b_{\mathrm{ESS}}$ \COMMENT{ESS-binding}
\ENDIF
\end{algorithmic}
\end{algorithm}

Each bisection requires $\mathcal{O}(B \log(b_{\max}/\varepsilon))$ operations; with $B{=}4$, $b_{\max}{=}20$, $\varepsilon{=}0.01$, roughly 44 floating-point operations per batch, negligible beside the forward and backward passes.
We compute $\bstar$ at the micro-batch level ($B{=}4$) rather than the effective batch ($B{=}16$ after gradient accumulation) because $q$-score statistics exhibit sufficient variance within micro-batches: Spearman $r{=}0.699$ with the true real fraction, and at $B{=}16$ the adaptive advantage amplifies $3.4{\times}$ ($\Delta{=}{-}0.068{\pm}0.005$; \S\ref{sec:sensitivity}).

